&lt;td width=&quot;198&quot;&gt;
&lt;p&gt;Position:&lt;/p&gt;
&lt;/td&gt;
&lt;td width=&quot;522&quot;&gt;
&lt;p&gt;Racial Justice Center Director&lt;/p&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td width=&quot;198&quot;&gt;
&lt;p&gt;Department:&lt;/p&gt;
&lt;/td&gt;
&lt;td width=&quot;522&quot;&gt;
&lt;p&gt;Racial Justice Center&lt;/p&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td width=&quot;198&quot;&gt;
