&lt;/li&gt;
&lt;/ul&gt;
&lt;hr data-start=&quot;2862&quot; data-end=&quot;2865&quot;&gt;
&lt;h3&gt;&lt;span style=&quot;color: rgb(186, 55, 42);&quot;&gt;Compensation &amp;amp; Schedule:&lt;/span&gt;&lt;/h3&gt;
&lt;ul data-start=&quot;2899&quot; data-end=&quot;3101&quot;&gt;
&lt;li data-start=&quot;2899&quot; data-end=&quot;3006&quot;&gt;
&lt;p data-start=&quot;2901&quot; data-end=&quot;2917&quot;&gt;&lt;strong data-start=&quot;2901&quot; data-end=&quot;2915&quot;&gt;Pay range: $33-$35&lt;/strong&gt;&lt;/p&gt;
